if n_qubits < 2:
    raise ValueError("Random circuit requires at least 2 qubits.")

rng = random.Random(n_qubits if seed is None else seed)
circ = Circuit(n_qubits)

for layer in range(max(2, n_qubits)):
    choices = ("H", "Rx", "Ry") if layer == 0 else ("H", "Rx", "Ry", "Rz")
    for q in range(n_qubits):
        gate = rng.choice(choices)
        if gate == "H":
            circ.H(q)
        else:
            getattr(circ, gate)(round(rng.uniform(0.05, 1.95), 6), q)
    order = list(range(n_qubits))
    rng.shuffle(order)
    for control, target in zip(order[0::2], order[1::2]):
        circ.CX(control, target)

qasm = circuit_to_qasm_str(circ)
